




"use strict";












const STOP1 = 1;
const CONT2 = 2;


const CF = new Uint8Array(128);
CF[10] = STOP1; 
CF[59] = STOP1 | CONT2; 
CF[123] = STOP1 | CONT2; 
CF[125] = STOP1 | CONT2; 
CF[32] = CONT2; 
CF[13] = CONT2; 
CF[9] = CONT2; 





















const eachPotentialToken = (str, onToken) => {
	const len = str.length;
	let i = 0;
	outer: while (i < len) {
		const start = i;
		
		let cc = str.charCodeAt(i);
		while (cc > 127 || !(CF[cc] & STOP1)) {
			if (++i >= len) {
				onToken(start, i, false);
				break outer;
			}
			cc = str.charCodeAt(i);
		}
		
		while (cc < 128 && CF[cc] & CONT2) {
			if (++i >= len) {
				onToken(start, i, false);
				break outer;
			}
			cc = str.charCodeAt(i);
		}
		
		if (cc === 10) {
			i++;
			onToken(start, i, true);
		} else {
			onToken(start, i, false);
		}
	}
};









const splitIntoPotentialTokens = (str) => {
	const len = str.length;
	if (len === 0) return null;
	const results = [];
	let i = 0;
	outer: while (i < len) {
		const start = i;
		
		let cc = str.charCodeAt(i);
		while (cc > 127 || !(CF[cc] & STOP1)) {
			if (++i >= len) {
				results.push(str.slice(start, i));
				break outer;
			}
			cc = str.charCodeAt(i);
		}
		
		while (cc < 128 && CF[cc] & CONT2) {
			if (++i >= len) {
				results.push(str.slice(start, i));
				break outer;
			}
			cc = str.charCodeAt(i);
		}
		
		if (cc === 10) {
			i++;
		}
		results.push(str.slice(start, i));
	}
	return results;
};

module.exports = splitIntoPotentialTokens;
module.exports.eachPotentialToken = eachPotentialToken;
